matmul_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Tiled GEMM: C = A * B, all row-major [N, N] float32
// Each CTA computes a 128x128 tile of C with 256 threads,
// staging 128x8 A-tiles and 8x128 B-tiles in shared memory.
// Optimization: four-stage cp.async software pipeline that keeps up to
// three future k-tiles in flight while computing the current tile.
__device__ __forceinline__ void cp_async_16(void* smem_dst, void const* gmem_src) {
#if __CUDA_ARCH__ >= 800
  unsigned dst = static_cast<unsigned>(__cvta_generic_to_shared(smem_dst));
  asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" :: "r"(dst), "l"(gmem_src));
#else
  *reinterpret_cast<float4*>(smem_dst) = *reinterpret_cast<float4 const*>(gmem_src);
#endif
}
__device__ __forceinline__ void cp_async_4(void* smem_dst, void const* gmem_src) {
#if __CUDA_ARCH__ >= 800
  unsigned dst = static_cast<unsigned>(__cvta_generic_to_shared(smem_dst));
  asm volatile("cp.async.ca.shared.global [%0], [%1], 4;\n" :: "r"(dst), "l"(gmem_src));
#else
  *reinterpret_cast<float*>(smem_dst) = *reinterpret_cast<float const*>(gmem_src);
#endif
}
__device__ __forceinline__ void cp_async_commit_group() {
#if __CUDA_ARCH__ >= 800
  asm volatile("cp.async.commit_group;\n" ::);
#endif
}
template <int W>
__device__ __forceinline__ void cp_async_wait_group() {
#if __CUDA_ARCH__ >= 800
  asm volatile("cp.async.wait_group %0;\n" :: "n"(W));
#endif
}
__global__ static void __launch_bounds__(256) matmul_kernel(
    int M, int N, int K,
    float const* __restrict__ A,
    float const* __restrict__ B,
    float* __restrict__ C)
{
  constexpr int BM = 128;
  constexpr int BN = 128;
  constexpr int BK = 8;
  // Shared-memory bank-conflict reduction via layout transform.
  // Both operands are staged row-major with a +4-float skew so the
  // 16-byte cp.async copies stay contiguous/aligned, and every smem
  // read in the rank-k update below is either conflict-free or a
  // hardware broadcast.
  constexpr int LDA = BK + 4;   // A tile: [BM][LDA], k contiguous
  constexpr int LDB = BN + 4;   // B tile: [BK][LDB], n contiguous
  // Four-stage shared-memory pipeline (41 KB static shared memory)
  __shared__ float smemA[4][BM * LDA];
  __shared__ float smemB[4][BK * LDB];
  int const tid  = threadIdx.x;
  int const m0   = blockIdx.x * BM;
  int const n0   = blockIdx.y * BN;
  int const kmax = K / BK;
  // Stage one (BM x BK) A-tile and one (BK x BN) B-tile into shared
  // memory using asynchronous vectorized (16B) global->shared copies.
  auto load_tile = [&](int k_tile, int stage) {
    // A tile: 128 rows of 8 contiguous floats; one float4 per thread.
    {
      int const row = tid >> 1;        // 0..127
      int const kh  = (tid & 1) * 4;   // 0 or 4
      float const* src = A + (long)(m0 + row) * K + (long)k_tile * BK + kh;
      float*       dst = smemA[stage] + row * LDA + kh;
      cp_async_16(dst, src);
    }
    // B tile: rows of 128 contiguous floats; one float4 per thread.
    {
      int const kr = tid >> 5;         // 0..7
      int const nc = (tid & 31) * 4;   // 0..124
      float const* src = B + (long)(k_tile * BK + kr) * N + n0 + nc;
      float*       dst = smemB[stage] + kr * LDB + nc;
      cp_async_16(dst, src);
    }
  };
  // Warp-level tiling: the 256 threads form 8 warps arranged as a 2x4
  // warp grid over the 128x128 CTA tile, so each warp owns a 64x32
  // sub-tile. Inside a warp the 32 lanes form an 8x4 grid and each
  // lane accumulates an 8x8 register block (rows strided by 8 across
  // lanes, 8 contiguous columns per lane). Combined with the padded
  // smem layouts this keeps every shared-memory read a vectorized
  // 16-byte access that is either conflict-free or a hardware
  // broadcast, and keeps global stores coalesced.
  int const warp   = tid >> 5;   // warp id (0..7)
  int const lane   = tid & 31;   // lane id (0..31)
  int const warp_m = warp & 1;   // warp row (0..1): 64 rows each
  int const warp_n = warp >> 1;  // warp col (0..3): 32 cols each
  int const lane_m = lane & 7;   // lane row within warp (0..7)
  int const lane_n = lane >> 3;  // lane col within warp (0..3)
  float acc[8][8];
#pragma unroll
  for (int i = 0; i < 8; ++i) {
#pragma unroll
    for (int j = 0; j < 8; ++j) {
      acc[i][j] = 0.0f;
    }
  }
  // Prologue: fill the first three pipeline stages (empty commit groups
  // keep the wait_group depth uniform when K has fewer than three tiles)
  for (int p = 0; p < 3; ++p) {
    if (p < kmax) {
      load_tile(p, p);
    }
    cp_async_commit_group();
  }
  for (int k_tile = 0; k_tile < kmax; ++k_tile) {
    int const cur = k_tile & 3;
    // Keep the pipeline full: prefetch tile k+3 into the stage that was
    // consumed by the previous iteration, then wait only for the oldest
    // group (the current tile) to land.
    int const nxt = k_tile + 3;
    if (nxt < kmax) {
      load_tile(nxt, nxt & 3);
    }
    cp_async_commit_group();
    cp_async_wait_group<3>();  // allow the three newest groups to remain in flight
    __syncthreads();
    float const* sA = smemA[cur];
    float const* sB = smemB[cur];
    // Register-level double buffering (software pipeline) of the shared-
    // memory operand fragments: the A/B fragments for the second k-half
    // of the tile are prefetched into an alternate register buffer while
    // the FMAs for the first k-half are issuing, hiding shared-memory
    // load latency behind arithmetic instead of stalling the warp
    // between the two rank-k updates of each tile.
    int const rbase = warp_m * 64 + lane_m;      // rows rbase + 8*i
    int const cbase = warp_n * 32 + lane_n * 8;  // cols cbase + 0..7
    float a[2][8][4];
    float b[2][4][8];
    // Preload fragments for k-half 0 (vectorized float4 smem reads).
    // Preload fragments for k-half 0 (vectorized float4 smem reads).
#pragma unroll
    for (int i = 0; i < 8; ++i) {
      int const row = rbase + 8 * i;
      *reinterpret_cast<float4*>(a[0][i]) =
          *reinterpret_cast<float4 const*>(sA + row * LDA);
    }
#pragma unroll
    for (int kk = 0; kk < 4; ++kk) {
      *reinterpret_cast<float4*>(b[0][kk]) =
          *reinterpret_cast<float4 const*>(sB + kk * LDB + cbase);
      *reinterpret_cast<float4*>(b[0][kk] + 4) =
          *reinterpret_cast<float4 const*>(sB + kk * LDB + cbase + 4);
    }
    for (int g = 0; g < 2; ++g) {
      int const cbuf = g;
      int const nbuf = g ^ 1;
      // Prefetch k-half 1 fragments before computing k-half 0.
      if (g == 0) {
#pragma unroll
        for (int i = 0; i < 8; ++i) {
          int const row = rbase + 8 * i;
          *reinterpret_cast<float4*>(a[nbuf][i]) =
              *reinterpret_cast<float4 const*>(sA + row * LDA + 4);
        }
#pragma unroll
        for (int kk = 0; kk < 4; ++kk) {
          *reinterpret_cast<float4*>(b[nbuf][kk]) =
              *reinterpret_cast<float4 const*>(sB + (4 + kk) * LDB + cbase);
          *reinterpret_cast<float4*>(b[nbuf][kk] + 4) =
              *reinterpret_cast<float4 const*>(sB + (4 + kk) * LDB + cbase + 4);
        }
      }
#pragma unroll
      for (int kk = 0; kk < 4; ++kk) {
#pragma unroll
        for (int i = 0; i < 8; ++i) {
#pragma unroll
          for (int j = 0; j < 8; ++j) {
            acc[i][j] = fmaf(a[cbuf][i][kk], b[cbuf][kk][j], acc[i][j]);
          }
        }
      }
    }
    __syncthreads();
  }
  // Epilogue: vectorized float4 stores; each warp writes coalesced
  // 128B segments along n within its 64x32 sub-tile.
  int const gm = m0 + warp_m * 64 + lane_m;
  int const gn = n0 + warp_n * 32 + lane_n * 8;
#pragma unroll
  for (int i = 0; i < 8; ++i) {
    int const row = gm + 8 * i;
#pragma unroll
    for (int jj = 0; jj < 2; ++jj) {
      *reinterpret_cast<float4*>(C + (long)row * N + gn + 4 * jj) =
          make_float4(acc[i][jj * 4 + 0], acc[i][jj * 4 + 1],
                      acc[i][jj * 4 + 2], acc[i][jj * 4 + 3]);
    }
  }
}

