      (int)M, (int)N, (int)K,
      A_c.data_ptr<float>(),
      B_c.data_ptr<float>(),
      C.data_ptr<float>());

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE matmul launch failed: ",
              cudaGetErrorString(err));

  return C;
}
